INSERT INTO Bar (name, address) VALUES ('BarB', 'AddressB');

-- Insert Beers
INSERT INTO Beer (name, brewer) VALUES ('Beer1', 'Brewer1');
INSERT INTO Beer (name, brewer) VALUES ('Beer2', 'Brewer2');

-- Insert Drinker
INSERT INTO Drinker (name, address) VALUES ('D1', 'AddressD1');

-- Insert Frequents: D1 frequents only BarA
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('D1', 'BarA', 3);

-- Insert Serves: BarA serves Beer1; BarB serves Beer2
INSERT INTO Serves (bar, beer, price) VALUES ('BarA', 'Beer1', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('BarB', 'Beer2', 6.00);

-- Insert Likes: D1 likes Beer1
INSERT INTO Likes (drinker, beer) VALUES ('D1', 'Beer1');

